// Package todo defines the Todo type shared by every GoDo client and the
// server, along with parsing and formatting of todo.txt lines
// (https://github.com/todotxt/todo.txt).
//
// GoDo adds two tags to the standard syntax:
//
//   - id:  a ULID generated by the client that creates the todo. It never
//     changes.
//   - mod: a UTC RFC 3339 timestamp, updated whenever the todo changes.
package todo

import (
	"crypto/rand"
	"time"

	"github.com/oklog/ulid/v2"
)

// Todo is a single todo item.
//
// Description is the source of truth for the todo's text. Projects, Contexts,
// and Tags are derived from it when parsing and are not used when formatting,
// so editing them has no effect on the output of Line or String.
type Todo struct {
	// ID is the todo's ULID, from the id: tag. It is empty for a line that was
	// added by hand and hasn't been assigned an ID yet.
	ID string

	Completed bool

	// Priority is "" or a single uppercase letter A-Z.
	Priority string

	// CompletedAt and CreatedAt are the optional todo.txt dates. A zero value
	// means the date is absent.
	CompletedAt time.Time
	CreatedAt   time.Time

	// Description is everything after the priority and dates, with the id:
	// and mod: tags removed. Other +projects, @contexts, and key:value tags
	// stay in place.
	Description string

	// Projects, Contexts, and Tags are derived from Description. Tags never
	// contains id or mod.
	Projects []string
	Contexts []string
	Tags     map[string]string

	// Mod is the time of the last change, from the mod: tag.
	Mod time.Time

	// Archived is not encoded in the line. In local mode it is determined by
	// which file the line is in: todo.txt or done.txt.
	Archived bool

	// Version is the server's version of this todo, used to detect conflicts.
	// It is not encoded in the line. Zero means the server has never seen it.
	Version int
}

// NewID returns a new ULID string for use as a todo ID.
func NewID() string {
	return ulid.MustNew(ulid.Timestamp(time.Now()), rand.Reader).String()
}
